package com.kxh.aiagent.agent.progress;

import com.fasterxml.jackson.annotation.JsonInclude;
import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.time.Instant;

@JsonInclude(JsonInclude.Include.NON_NULL)
public record AgentProgressEvent(
        String type,
        String agentName,
        String content,
        String stage,
        int totalStages,
        long timestamp
) {
    private static final ObjectMapper mapper = new ObjectMapper();

    public AgentProgressEvent {
        if (timestamp == 0) {
            timestamp = Instant.now().toEpochMilli();
        }
    }

    public static AgentProgressEvent agentStart(String agentName, String stage, int totalStages) {
        return new AgentProgressEvent("agent_start", agentName, null, stage, totalStages, 0);
    }

    public static AgentProgressEvent agentStart(String agentName) {
        return new AgentProgressEvent("agent_start", agentName, null, null, 0, 0);
    }

    public static AgentProgressEvent agentMessage(String agentName, String content) {
        return new AgentProgressEvent("agent_message", agentName, content, null, 0, 0);
    }

    public static AgentProgressEvent agentDone(String agentName, String stage, int totalStages) {
        return new AgentProgressEvent("agent_done", agentName, null, stage, totalStages, 0);
    }

    public static AgentProgressEvent agentDone(String agentName) {
        return new AgentProgressEvent("agent_done", agentName, null, null, 0, 0);
    }

    public static AgentProgressEvent agentError(String agentName, String error) {
        return new AgentProgressEvent("agent_error", agentName, error, null, 0, 0);
    }

    public static AgentProgressEvent progress(String agentName, String message) {
        return new AgentProgressEvent("progress", agentName, message, null, 0, 0);
    }

    public String toJson() {
        try {
            return mapper.writeValueAsString(this);
        } catch (JsonProcessingException e) {
            return "{\"type\":\"error\",\"content\":\"json serialize failed\"}";
        }
    }
}

package com.kxh.aiagent.agent.progress;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.io.IOException;

public class StreamProgressEmitter {

    private static final Logger log = LoggerFactory.getLogger(StreamProgressEmitter.class);

    private final SseEmitter emitter;

    public StreamProgressEmitter(SseEmitter emitter) {
        this.emitter = emitter;
    }

    public void send(AgentProgressEvent event) {
        try {
            emitter.send(SseEmitter.event()
                    .name("progress")
                    .data(event.toJson()));
        } catch (IOException e) {
            log.debug("SSE send failed, client may have disconnected: {}", e.getMessage());
        }
    }

    public void agentStart(String agentName) {
        send(AgentProgressEvent.agentStart(agentName));
    }

    public void agentStart(String agentName, int stage, int totalStages) {
        send(AgentProgressEvent.agentStart(agentName, String.valueOf(stage), totalStages));
    }

    public void agentMessage(String agentName, String content) {
        send(AgentProgressEvent.agentMessage(agentName, content));
    }

    public void agentDone(String agentName) {
        send(AgentProgressEvent.agentDone(agentName));
    }

    public void agentDone(String agentName, int stage, int totalStages) {
        send(AgentProgressEvent.agentDone(agentName, String.valueOf(stage), totalStages));
    }

    public void agentError(String agentName, String error) {
        send(AgentProgressEvent.agentError(agentName, error));
    }

    public void progress(String agentName, String message) {
        send(AgentProgressEvent.progress(agentName, message));
    }

    public void sendRaw(String content) {
        try {
            emitter.send(SseEmitter.event()
                    .name("message")
                    .data(content));
        } catch (IOException e) {
            log.debug("SSE raw send failed: {}", e.getMessage());
        }
    }

    public void complete() {
        try {
            emitter.send(SseEmitter.event().name("done").data("[DONE]"));
            emitter.complete();
        } catch (IOException e) {
            log.debug("SSE complete failed: {}", e.getMessage());
        }
    }

    public void error(Throwable e) {
        try {
            emitter.send(SseEmitter.event().name("error").data(e.getMessage()));
        } catch (IOException ignored) {
        }
        emitter.completeWithError(e);
    }
}

