package com.kxh.aiagent.controller;

import com.alibaba.cloud.ai.graph.RunnableConfig;
import com.alibaba.cloud.ai.graph.agent.ReactAgent;
import com.alibaba.cloud.ai.graph.agent.flow.agent.ParallelAgent;
import com.alibaba.cloud.ai.graph.agent.flow.agent.SequentialAgent;
import com.kxh.aiagent.agent.progress.StreamProgressEmitter;
import jakarta.annotation.Resource;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.ai.chat.messages.AssistantMessage;
import org.springframework.http.MediaType;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.util.UUID;
import java.util.concurrent.CompletableFuture;

@RestController
@RequestMapping("/v2/agent")
public class ReactAgentController {

    private static final Logger log = LoggerFactory.getLogger(ReactAgentController.class);

    @Resource
    private ReactAgent generalAgent;

    @Resource
    private ReactAgent investAgent;

    @Resource
    private SequentialAgent investReportPipeline;

    @Resource
    private ReactAgent dataCollectorAgent;

    @Resource
    private ParallelAgent analysisParallelAgent;

    @Resource
    private ReactAgent investmentAdvisorAgent;

    @Resource
    private ReactAgent reportAgent;

    // ==================== 通用Agent ====================

    @GetMapping(value = "/chat", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public SseEmitter chat(@RequestParam String message,
                           @RequestParam(required = false) String threadId) {
        if (threadId == null || threadId.isBlank()) {
            threadId = UUID.randomUUID().toString();
        }

        SseEmitter emitter = new SseEmitter(300_000L);
        StreamProgressEmitter progress = new StreamProgressEmitter(emitter);
        String finalThreadId = threadId;

        CompletableFuture.runAsync(() -> {
            try {
                RunnableConfig config = RunnableConfig.builder()
                        .threadId(finalThreadId)
                        .build();

                progress.agentStart("kxhAgent");
                progress.progress("kxhAgent", "正在分析您的问题...");

                AssistantMessage result = generalAgent.call(message, config);

                progress.sendRaw(result.getText());
                progress.agentDone("kxhAgent");
                progress.complete();
            } catch (Exception e) {
                log.error("Agent执行异常: {}", e.getMessage(), e);
                progress.agentError("kxhAgent", e.getMessage());
                progress.error(e);
            }
        });

        return emitter;
    }

    // ==================== 投资Agent ====================

    @GetMapping(value = "/invest", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public SseEmitter invest(@RequestParam String message,
                             @RequestParam(required = false) String threadId) {
        if (threadId == null || threadId.isBlank()) {
            threadId = UUID.randomUUID().toString();
        }

        SseEmitter emitter = new SseEmitter(300_000L);
        StreamProgressEmitter progress = new StreamProgressEmitter(emitter);
        String finalThreadId = threadId;

        CompletableFuture.runAsync(() -> {
            try {
                RunnableConfig config = RunnableConfig.builder()
                        .threadId(finalThreadId)
                        .build();

                progress.agentStart("InvestAgent");
                progress.progress("InvestAgent", "正在分析投资需求，准备调用相关工具...");

                AssistantMessage result = investAgent.call(message, config);

                progress.sendRaw(result.getText());
                progress.agentDone("InvestAgent");
                progress.complete();
            } catch (Exception e) {
                log.error("InvestAgent执行异常: {}", e.getMessage(), e);
                progress.agentError("InvestAgent", e.getMessage());
                progress.error(e);
            }
        });

        return emitter;
    }

    // ==================== 投资研报流水线（4阶段手动编排 + 进度追踪）====================

    @GetMapping(value = "/invest/analysis", produces = MediaType.TEXT_EVENT_STREAM_VALUE)
    public SseEmitter investAnalysis(@RequestParam String message,
                                     @RequestParam(required = false) String threadId) {
        if (threadId == null || threadId.isBlank()) {
            threadId = UUID.randomUUID().toString();
        }

        SseEmitter emitter = new SseEmitter(600_000L);
        StreamProgressEmitter progress = new StreamProgressEmitter(emitter);
        String finalThreadId = threadId;
        String contextThreadId = finalThreadId;

        CompletableFuture.runAsync(() -> {
            try {
                RunnableConfig config = RunnableConfig.builder()
                        .threadId(contextThreadId)
                        .build();

                // ========== Stage 1/4: 数据采集 ==========
                progress.agentStart("数据采集Agent", 1, 4);
                progress.progress("数据采集Agent", "开始采集公司基本信息、财务报表、估值数据、行业对比...");

                AssistantMessage stage1Result = dataCollectorAgent.call(message, config);
                String dataOutput = stage1Result.getText();

                progress.sendRaw(dataOutput);
                progress.agentDone("数据采集Agent", 1, 4);

                // ========== Stage 2/4: 8Agent并行分析 ==========
                progress.agentStart("并行分析集群 (8个Agent)", 2, 4);
                progress.progress("并行分析集群",
                        "8个分析Agent开始并行工作：商业模式 / 行业分析 / 杜邦分析 / 盈利能力 / 成长性 / 现金流 / 估值 / 风险识别");

                AssistantMessage stage2Result = analysisParallelAgent.call(dataOutput, config);
                String analysisOutput = stage2Result.getText();

                progress.sendRaw(analysisOutput);
                progress.agentDone("并行分析集群 (8个Agent)", 2, 4);

                // ========== Stage 3/4: 综合投资建议 ==========
                progress.agentStart("投资建议Agent", 3, 4);
                progress.progress("投资建议Agent", "综合8个维度分析结论，生成投资评级和建议...");

                AssistantMessage stage3Result = investmentAdvisorAgent.call(analysisOutput, config);
                String adviceOutput = stage3Result.getText();

                progress.sendRaw(adviceOutput);
                progress.agentDone("投资建议Agent", 3, 4);

                // ========== Stage 4/4: 研报生成 ==========
                progress.agentStart("研报生成Agent", 4, 4);
                progress.progress("研报生成Agent", "正在生成Markdown/PDF格式的专业投资研报...");

                AssistantMessage stage4Result = reportAgent.call(adviceOutput, config);
                String reportOutput = stage4Result.getText();

                progress.sendRaw(reportOutput);
                progress.agentDone("研报生成Agent", 4, 4);

                progress.complete();
            } catch (Exception e) {
                log.error("投资研报流水线执行异常: {}", e.getMessage(), e);
                progress.agentError("投资研报流水线", e.getMessage());
                progress.error(e);
            }
        });

        return emitter;
    }
}

